pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an arbitrary depositor address and an arbitrary deposit amount
    function testFuzz_property(address depositor, uint256 depositAmount) public {
        // admissible domain: depositor must be a non-zero address and depositAmount must be > 0
        vm.assume(depositor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint256).max);

        // fund the depositor so it can send ETH to c
        vm.deal(depositor, depositAmount);

        // depositor makes a payable call to c to trigger fallback and increase contract balance
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed in test setup");

        // sanity: contract now has positive balance
        assert(address(c).balance > 0);

        // owner (deployer) calls withdrawAll
        // set msg.sender to the owner (the test contract deployer is the owner since setUp used new C())
        // call withdrawAll and observe final contract balance
        c.withdrawAll();

        // General property: after owner calls withdrawAll on the correct contract, its balance is zero.
        // The mutant that replaces withdrawAll with withdraw(0) will leave a positive balance for some inputs,
        // so this assertion distinguishes them.
        assertTrue(address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving the scenario
    function run(address attacker, uint depositAmount, uint withdrawAmount) public {
        // ensure this test contract has enough ETH to deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // send deposit to C via fallback by calling with value
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Owner (the original deployer of C) should be able to withdraw all via withdrawAll
        // We call withdrawAll; under P this is restricted to owner, so if this contract is not owner
        // the call will revert. To make the test general, we attempt withdrawAll and capture whether it reverted.
        bool revertedOwnerWithdraw;
        try c.withdrawAll() {
            revertedOwnerWithdraw = false;
        } catch {
            revertedOwnerWithdraw = true;
        }

        // Now attempt a withdraw call of withdrawAmount and observe c balance afterwards
        // This call will succeed under M by anyone, but under P only owner can withdraw.
        bool revertedWithdraw;
        try c.withdraw(withdrawAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Observe contract balance
        uint bal = address(c).balance;

        // General rule: if withdraw by non-owner reverts (i.e., onlyOwner enforced), then balance must be zero only if owner successfully withdrewAll earlier
        // To keep rule simple and distinguishing: assert that if a non-owner's withdraw call reverted, then either withdrawAll succeeded (so balance == 0) or balance equals the depositAmount
        // This captures that under P only owner can change balance; under M a non-owner withdraw may succeed and reduce balance below depositAmount without withdrawAll.
        assert( revertedWithdraw == true ? ( (revertedOwnerWithdraw == false && bal == 0) || bal == depositAmount ) : bal <= depositAmount );
    }

    // allow this contract to receive ETH for testing deposits
    receive() external payable {}
}

