pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker address and amount to send to sendMoney and then attempt withdraw
    function testFuzz_property(address attacker, uint256 sendValue) public {
        // keep sendValue in a sensible wide range but not too huge
        sendValue = bound(sendValue, 0, 1 ether);
        // ensure attacker is not zero address
        vm.assume(attacker != address(0));

        // fund the contract initially with some ETH so withdrawals matter
        vm.deal(address(this), 1 ether);
        // deposit into contract via fallback by sending plain ether from this contract
        // we use this contract (test runner) as the depositor
        (bool okSend,) = address(c).call{value: 0.5 ether}("");
        require(okSend, "initial deposit failed");

        // record balance before any interactions
        uint256 before = address(c).balance;

        // Deploy a helper that will receive the low-level call from c; it will accept the call
        // and do nothing (a normal callee). We still deploy it so we can pass a contract address
        // rather than an EOA to ensure realistic behaviour.
        HelperReceiver helper = new HelperReceiver();

        // Now perform sendMoney from the contract owner (setUp deployer is owner)
        // We let owner call sendMoney and target the helper with some value and empty data
        vm.deal(address(this), sendValue);
        vm.prank(address(this));
        // Call sendMoney; it may forward value to helper
        c.sendMoney(address(helper), sendValue, "");

        // After sendMoney, a general rule of the correct contract: only owner can withdraw funds,
        // so the balance must be >= balance after any external actor attempts to withdraw.
        // To check for the mutant we now impersonate attacker and attempt withdraw()
        vm.deal(attacker, 0.1 ether);
        vm.prank(attacker);
        // try to call withdraw on behalf of attacker; if it succeeds on the mutant it will lower balance
        // capture whether call succeeded
        bool ok;
        try c.withdraw({ _value: 0 }) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: in the correct contract, attacker (non-owner) cannot withdraw, so the contract balance
        // must remain >= before - sendValue (i.e., not further decreased by a non-owner withdraw). We observe c
        // only via address(c).balance. For our test we assert that either the attacker call failed (ok == false)
        // OR the balance did not decrease due to the attack (address(c).balance >= before - sendValue).
        // This is a single assertTrue reading c and reflecting the universal property: only owner can reduce balance.
        assertTrue(!ok || address(c).balance >= before - sendValue);
    }
}

contract HelperReceiver {
    receive() external payable {}
    fallback() external payable {}
}

