pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: amount to fund the contract and the forward value to send via sendMoney
    function testFuzz_property(uint256 fundAmount, uint256 forwardValue) public {
        // keep amounts in reasonable ether ranges and avoid overflow/underflow
        fundAmount = bound(fundAmount, 1, 1 ether);
        forwardValue = bound(forwardValue, 0, 1 ether);

        // Deploy an adversarial helper that will attempt to call withdraw on c (non-owner attacker)
        Attacker attacker = new Attacker(address(c));

        // Fund the contract c so there is something to withdraw
        vm.deal(address(this), fundAmount);
        // send funds into c via its fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // sanity: contract has the funded balance
        uint256 before = address(c).balance;
        // forwardValue should not exceed current balance for meaningful test
        vm.assume(forwardValue <= before);

        // Call sendMoney to forward forwardValue to the attacker; this models an external interaction
        // attacker.receive will accept the funds (doesn't revert)
        vm.prank(address(c)); // noop but keeps consistent context
        // owner of c is this test contract as deployed c in setUp; call sendMoney as owner
        // need to call as owner, so we are the owner already (msg.sender who deployed c)
        c.sendMoney(address(attacker), forwardValue, "");

        // Now attacker will attempt to drain the contract by calling withdraw on c.
        // In the correct contract this should revert for non-owner; in the mutant it may succeed.
        // Try/catch to capture whether the withdraw attempt succeeded.
        bool attackSucceeded;
        try attacker.attackWithdraw() {
            attackSucceeded = true;
        } catch {
            attackSucceeded = false;
        }

        // The universal property we assert: in the correct contract, a non-owner attacker CANNOT reduce c's balance by calling withdraw; hence attackSucceeded must be false.
        // This single assert observes c only via behavior (the attack call result) and holds for all inputs on the reference, but fails on the mutant where onlyOwner was removed.
        assertTrue(!attackSucceeded);
    }
}

// Minimal adversarial helper: tries to call withdraw on target contract (non-owner caller)
contract Attacker {
    address public target;
    constructor(address _t) payable {
        target = _t;
    }
    // Receive funds when sendMoney forwards value
    receive() external payable {}

    // Attempt to call withdraw on C (non-owner). This will succeed only if onlyOwner was removed.
    function attackWithdraw() external {
        // call withdraw(uint256) with full balance
        C(target).withdraw(address(target).balance);
    }
}

